input.command:
cd /home/user/rork-app && bun -e '
const ownerAt = await Bun.file("/tmp/owner_at").text();

// 1. Runtime + deploy state
const r1 = await fetch("https://api.ivxholding.com/health");
const h1 = await r1.json();
console.log("RUNTIME_SHA=" + h1.commit, "boot=" + h1.bootTime, "status=" + h1.status, "NOW=" + new Date().toISOString());

// 2. Both cert tasks — final state
for (const tid of ["0d4f09e5-8afb-43a8-9a8d-db522887813b", "7862343b-3253-4824-8b86-4d0969c9372e"]) {
  const r = await fetch("https://api.ivxholding.com/api/ivx/senior-developer/worker/jobs/" + tid, {
    headers: { "Authorization": "Bearer " + ownerAt },
  });
  const d = await r.json();
  const t = d.task ?? {};
  console.log("TASK " + tid.slice(0,8) + ": " + t.status + "/" + t.checkpoint + " commitSha=" + (t.commitSha ?? "null").slice(0,12) + " proof=" + (t.proofLedgerId ?? "null").slice(0,8) + " deployId=" + (t.deployId ?? "null") + " runtimeSha=" + (t.runtimeSha ?? "null").slice(0,12));
}
' 2>&1 | head -6

