input.command:
cd /home/user/rork-app && bun -e '
// Re-mint owner token (email-only passwordless login)
const r = await fetch("https://api.ivxholding.com/api/ivx/owner-passwordless-login", {
  method: "POST",
  headers: { "Content-Type": "application/json" },
  body: JSON.stringify({ email: "iperez4242@gmail.com" }),
});
const d = await r.json();
console.log("LOGIN=" + r.status, "hasAt=" + !!d.accessToken, "hasRt=" + !!d.refreshToken);
if (d.accessToken) {
  await Bun.write("/tmp/owner_at", d.accessToken);
  if (d.refreshToken) await Bun.write("/tmp/owner_rt", d.refreshToken);
  console.log("TOKEN_LEN=" + d.accessToken.length);
}
' 2>&1 | head -5

